import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Server gameplay policy","description":"","frontmatter":{"pageId":"admins/gameplay-policy","contentRevision":1},"headers":[],"relativePath":"en/admins/gameplay-policy.md","filePath":"en/admins/gameplay-policy.md"}'),r={name:"en/admins/gameplay-policy.md"};function o(s,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="server-gameplay-policy" tabindex="-1">Server gameplay policy <a class="header-anchor" href="#server-gameplay-policy" aria-label="Permalink to &quot;Server gameplay policy&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Before opening a server, publish rules for economy, newcomer protection, raids, incidents and storage. Economy controls parcel/lot limits, fees, storage charges and threat restrictions. Raids controls raider counts, cooldowns, loot, peaceful mode and lifetimes. Incidents controls its catalog, queue and prices. Live controls deadlines, pauses and stream limits.</p><p>Integrity controls dev mode, wealth changes and scenario modifications. Hygiene archives sufficiently old inactive colonies under wealth/age conditions and defines public wealth bands. Disabling a check requires understanding its semantics, not assigning an arbitrary zero.</p><p>For an incident, first freeze the relevant subsystem, preserve IDs and audit, inspect escrow, then cancel or unfreeze. Verify mail returns.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Auction, procurement, social and influence constants are not necessarily configurable. Storage charges may create debt. A freeze defers auction settlement; it is not an automatic refund. Influence does not grant territorial rights.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./configuration">Configuration reference</a></li><li><a href="./administration">Panel and moderation</a></li><li><a href="./../players/raids-incidents">Raids and paid incidents</a></li></ul>',10)])])}const f=a(r,[["render",o]]);export{u as __pageData,f as default};
